{
  "name": "opencode-plugin-resumator",
  "version": "0.6.1",
  "description": "OpenCode plugin for per-turn project context injection, technical state retention, and native compaction enrichment.",
  "author": "Lucas Moraes",
  "type": "module",
  "main": "./index.js",
  "exports": {
    ".": "./index.js"
  },
  "files": [
    "index.js",
    "index.internal.js",
    "README.md",
    "LICENSE"
  ],
  "scripts": {
    "test": "node --test",
    "prepublishOnly": "npm run test",
    "release": "npm test && git tag v$npm_package_version && git push origin && git push origin v$npm_package_version"
  },
  "keywords": [
    "opencode",
    "opencode-plugin",
    "context-compression",
    "file-tree",
    "llm-memory",
    "context-window"
  ],
  "license": "MIT",
  "repository": {
    "type": "git",
    "url": "git+https://github.com/lucas-moraes/opencode-plugin-resumator.git"
  },
  "bugs": {
    "url": "https://github.com/lucas-moraes/opencode-plugin-resumator/issues"
  },
  "homepage": "https://github.com/lucas-moraes/opencode-plugin-resumator#readme",
  "engines": {
    "node": ">=18.0.0"
  },
  "dependencies": {
    "@toon-format/toon": "^4.1.1",
    "ignore": "^7.0.6",
    "smol-toml": "^1.8.0",
    "tiktoken": "^1.0.22"
  }
}
